  (* [comment removed for export] *)
  Lemma ts_ld_ctx : forall s ck (k : word -> M R) P,
    Rep A (ms_mem s) -> WIN s -> cvalid ck -> clen ck = 8 -> 0 <= a_ctx A ck < 2^64 ->
    tsafe (k (Z_to_bv 64 (a_ctx A ck)) s) P ->
    tsafe ((x <- m_ld (Z_to_bv 64 (caddr ck)) ;; k x) s) P.
Proof.
