  (* [comment removed for export] *)
  Lemma ts_lbu_ctx : forall s ck (k : word -> M R) P,
    Rep A (ms_mem s) -> WIN s -> cvalid ck -> clen ck = 1 -> 0 <= a_ctx A ck < 256 ->
    tsafe (k (Z_to_bv 64 (a_ctx A ck)) s) P ->
    tsafe ((x <- m_lbu (Z_to_bv 64 (caddr ck)) ;; k x) s) P.
