  (* [comment removed for export] *)
  Lemma ts_lhu_size_class : forall s j (k : word -> M R) P,
    rodata_clear (ms_mem s) -> WIN s -> 0 <= j < 48 ->
    tsafe (k (Z_to_bv 64 (size_class j)) s) P ->
    tsafe ((x <- m_lhu (Z_to_bv 64 (T_SIZE_CLASSES + 2 * j)) ;; k x) s) P.
