Section Steps2.
  Context {R : Type}.
  Variable A : astate.
  Hypothesis HW : WF A.

  (* [comment removed for export] *)
  Lemma ts_lbu_mbyte : forall s a v (k : word -> M R) P,
    WIN s -> mbyte (ms_mem s) a = Some v -> 0 <= a < alloc_ceiling ->
    tsafe (k (Z_to_bv 64 v) s) P ->
